// ============================================================
const NORMALIZE_NODE = 'Normalize Lead Details';
const CONFIG_NODE    = 'Set: Sequence Configuration';
// ============================================================

const lead   = $(NORMALIZE_NODE).first().json;
const config = $(CONFIG_NODE).first().json;
const allItems = $input.all();

// Extract Gemini array response
let rawText = '';
for (const item of allItems) {
  const text = item.json?.content?.parts?.[0]?.text
    || item.json?.candidates?.[0]?.content?.parts?.[0]?.text
    || item.json?.output || '';
  if (text && text.includes('"touch"')) {
    rawText = text;
    break;
  }
}

const cleaned = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

let emails = [];
try {
  emails = JSON.parse(cleaned);
  if (!Array.isArray(emails)) emails = [];
} catch (e) {
  // Fallback — generate generic emails for all 5 touches
  const subjects = [
    `Checking in about ${lead.propertyAddress}`,
    `A thought about ${lead.propertyAddress}`,
    `Activity near ${lead.propertyAddress}`,
    `Still interested in ${lead.propertyAddress}?`,
    `Closing the loop — ${lead.propertyAddress}`
  ];
  const bodies = [
    `Hi ${lead.leadName},\n\nI wanted to reconnect about ${lead.propertyAddress} — it's a property I think could be a great fit for you and I'd love to chat if you're still considering your options.`,
    `Hi ${lead.leadName},\n\nI've been keeping an eye on the market around ${lead.propertyAddress} and wanted to share that properties in this area are moving quickly — happy to give you a full update if that would be useful.`,
    `Hi ${lead.leadName},\n\nThere's been quite a bit of interest from buyers in the ${lead.propertyAddress} area recently — just wanted to make sure you're still in the loop in case timing is a factor for you.`,
    `Hi ${lead.leadName},\n\nI just wanted to quickly check in — are you still considering ${lead.propertyAddress} or has your situation changed? Happy to pick up where we left off whenever suits you.`,
    `Hi ${lead.leadName},\n\nI don't want to keep filling your inbox, so this will be my last note about ${lead.propertyAddress} for now — but please do reach out any time if your plans change. Wishing you all the best in your search.`
  ];
  emails = subjects.map((s, i) => ({
    touch: i + 1,
    email_subject: s,
    email_body: bodies[i]
  }));
}

// Ensure exactly 5 emails
while (emails.length < 5) {
  emails.push({
    touch: emails.length + 1,
    email_subject: `Following up — ${lead.propertyAddress}`,
    email_body: `Hi ${lead.leadName},\n\nJust wanted to follow up once more about ${lead.propertyAddress}. Please don't hesitate to reach out if you have any questions.`
  });
}

// HTML formatter
function formatEmailHtml(text, agentName, agentEmail) {
  if (!text) return '';
  const paragraphs = text
    .split(/\n\s*\n/)
    .map(p => p.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  const body = paragraphs.map(p => `<p>${p}</p>`).join('');
  return `<div style="font-family:Arial,sans-serif;max-width:600px;color:#333;">
    ${body}
    <p style="color:#666;font-size:13px;margin-top:24px;">
      ${agentName}<br>${agentEmail}
    </p>
  </div>`;
}

const e = emails;

return [{
  json: {
    // Lead details
    sequenceId:          lead.sequenceId,
    leadName:            lead.leadName,
    leadEmail:           lead.leadEmail,
    leadPhone:           lead.leadPhone,
    propertyAddress:     lead.propertyAddress,
    propertyUrl:         lead.propertyUrl,
    propertyDescription: lead.propertyDescription,
    leadBackground:      lead.leadBackground,
    startDate:           lead.startDate,
    timestamp:           lead.timestamp,
    source:              lead.source,

    // All 5 email subjects and bodies (plain text — stored in Sheets)
    touch1Subject: e[0]?.email_subject || '',
    touch1Body:    e[0]?.email_body    || '',
    touch2Subject: e[1]?.email_subject || '',
    touch2Body:    e[1]?.email_body    || '',
    touch3Subject: e[2]?.email_subject || '',
    touch3Body:    e[2]?.email_body    || '',
    touch4Subject: e[3]?.email_subject || '',
    touch4Body:    e[3]?.email_body    || '',
    touch5Subject: e[4]?.email_subject || '',
    touch5Body:    e[4]?.email_body    || '',

    // Touch 1 HTML for immediate sending
    touch1Html: formatEmailHtml(
      e[0]?.email_body || '',
      config.AGENT_NAME,
      config.AGENT_EMAIL
    ),

    // Config
    config
  }
}];

const allItems = $input.all();
let rawText = '';

for (const item of allItems) {
  const text = item.json?.content?.parts?.[0]?.text
    || item.json?.candidates?.[0]?.content?.parts?.[0]?.text
    || item.json?.output || '';
  if (text && text.includes('sentiment')) {
    rawText = text;
    break;
  }
}

const cleaned = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    sentiment: 'Neutral',
    reasoning: 'Unable to classify — review manually.',
    summary: 'Reply received — manual review recommended.'
  };
}

// Extract sender email from reply
const gmailData = $('Gmail: Watch for Replies').first().json;
// const fetchData = $('Gmail: Fetch Full Reply').first().json;

// const senderRaw = fetchData.from || gmailData.From || '';
// const senderEmail = typeof senderRaw === 'object'
//   ? senderRaw.value?.[0]?.address || senderRaw.text?.match(/<([^>]+)>/)?.[1] || ''
//   : String(senderRaw).match(/<([^>]+)>/)?.[1] || senderRaw;
const replyData  = $('Extract Latest Reply').first().json;
const senderRaw  = replyData.from || '';
const senderEmail = String(senderRaw)
  .match(/<([^>]+)>/)?.[1] || senderRaw.trim();
const replyText  = replyData.body || '';

// const replyText = fetchData.text || fetchData.snippet || gmailData.snippet || '';

return [{
  json: {
    sentiment:   parsed.sentiment,
    reasoning:   parsed.reasoning,
    summary:     parsed.summary,
    senderEmail: senderEmail.trim(),
    replyText,
    timestamp:   new Date().toISOString()
  }
}];

const replyData  = $('Extract Latest Reply').first().json;
const sentiment  = $('Parse Sentiment').first().json;
const threadId   = replyData.threadId || '';
const allRows    = $input.all().map(i => i.json);

// Match by Thread ID — most reliable
let match = allRows.find(row =>
  String(row['Thread ID'] || '').trim() === threadId.trim() &&
  row['Status'] !== 'Completed' &&
  row['Status'] !== 'Responded'
);
// let match = allRows.find(row =>
//   row['Status'] !== 'Completed' &&
//   row['Status'] !== 'Responded'
// );

// Fallback — match by sender email if thread ID not found
if (!match) {
  const senderRaw   = replyData.from || '';
  const senderEmail = String(senderRaw)
    .match(/<([^>]+)>/)?.[1]
    || senderRaw.replace(/.*<(.+)>.*/, '$1')
    || senderRaw.trim();

  match = allRows.find(row =>
    String(row['Email'] || '').toLowerCase().trim() ===
    senderEmail.toLowerCase().trim() &&
    row['Status'] !== 'Completed' &&
    row['Status'] !== 'Responded'
  );
}
if (!match) {
  return [{
    json: {
      sequenceFound: false,
      threadId,
      debug: allRows.map(r => ({
        id: r['Sequence ID'],
        email: r['Email'],
        threadId: r['Thread ID'],
        status: r['Status']
      }))
    }
  }];
}

return [{
  json: {
    sequenceFound:   true,
    sequenceId:      match['Sequence ID'],
    leadName:        match['Lead Name'],
    leadEmail:       match['Email'],
    currentTouch:    match['Current Touch'],
    status:          match['Status'],
    propertyAddress: match['Property Address'],
    sentiment:       sentiment.sentiment,
    reasoning:       sentiment.reasoning,
    summary:         sentiment.summary,
    replyText:       replyData.body
  }
}];

const config = $('Section C Configuration').first().json;
const allRows = $input.all().map(i => i.json);
const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric',
  month: 'long', day: 'numeric'
});

function escapeHtml(text) {
  if (!text) return 'N/A';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Categorise sequences
const active    = allRows.filter(r =>
  r['Status'] && r['Status'].startsWith('Touch') &&
  r['Status'] !== 'Completed');
const responded = allRows.filter(r => r['Status'] === 'Responded');
const completed = allRows.filter(r => r['Status'] === 'Completed');
const stopped   = allRows.filter(r => r['Status'] === 'Stopped');

// Build active sequences section
let activeHtml = '';
if (active.length > 0) {
  activeHtml = active.map(r => {
    const touchNum   = r['Current Touch'] || '?';
    const lastTouch  = r['Last Touch Date'] || 'Unknown';
    const nextTouchMap = { '1': 4, '2': 4, '3': 6, '4': 7 };
    const daysToNext = nextTouchMap[String(touchNum)] || '—';

    return `
      <tr style="border-bottom:1px solid #eee;">
        <td style="padding:10px 8px;">
          <strong>${escapeHtml(r['Lead Name'])}</strong><br>
          <span style="color:#666;font-size:13px;">
            ${escapeHtml(r['Property Address'])}
          </span>
        </td>
        <td style="padding:10px 8px;text-align:center;">
          <span style="background:#3498db;color:white;padding:4px 10px;
            border-radius:12px;font-size:13px;">
            Touch ${escapeHtml(String(touchNum))} of 5
          </span>
        </td>
        <td style="padding:10px 8px;color:#666;font-size:13px;">
          Last: ${escapeHtml(lastTouch)}<br>
          Next: ~${daysToNext} days
        </td>
      </tr>`;
  }).join('');
}

// Build responded section
let respondedHtml = '';
if (responded.length > 0) {
  respondedHtml = responded.map(r => `
    <tr style="border-bottom:1px solid #eee;">
      <td style="padding:10px 8px;">
        <strong>${escapeHtml(r['Lead Name'])}</strong>
      </td>
      <td style="padding:10px 8px;">
        ${escapeHtml(r['Property Address'])}
      </td>
      <td style="padding:10px 8px;">
        <span style="color:${r['Reply Sentiment'] === 'Hot'
          ? '#27ae60' : r['Reply Sentiment'] === 'Unsubscribe'
          ? '#e74c3c' : '#f39c12'};">
          ${escapeHtml(r['Reply Sentiment'] || 'Unknown')}
        </span>
      </td>
    </tr>`).join('');
}

// Full digest HTML
const digestHtml = `
  <div style="font-family:Arial,sans-serif;max-width:700px;margin:0 auto;color:#333;">
    <div style="background:#1a1a2e;color:white;padding:24px;border-radius:8px 8px 0 0;">
      <h2 style="margin:0;">🌅 Drip Campaign Morning Digest</h2>
      <p style="margin:8px 0 0 0;opacity:0.8;">${today}</p>
    </div>
    <div style="background:#f8f9fa;padding:12px 24px;border-bottom:1px solid #ddd;">
      <p style="margin:0;font-size:14px;">
        Active: <strong>${active.length}</strong> &nbsp;|&nbsp;
        Responded: <strong>${responded.length}</strong> &nbsp;|&nbsp;
        Completed: <strong>${completed.length}</strong> &nbsp;|&nbsp;
        Stopped: <strong>${stopped.length}</strong>
      </p>
    </div>
    <div style="padding:24px;background:white;">
      ${active.length > 0 ? `
        <h3 style="color:#1a1a2e;margin:0 0 12px 0;">
          📧 Active Sequences (${active.length})
        </h3>
        <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:24px;">
          <thead>
            <tr style="background:#f8f9fa;">
              <th style="padding:8px;text-align:left;">Lead</th>
              <th style="padding:8px;text-align:center;">Progress</th>
              <th style="padding:8px;text-align:left;">Timing</th>
            </tr>
          </thead>
          <tbody>${activeHtml}</tbody>
        </table>` : '<p style="color:#888;">No active sequences today.</p>'}

      ${responded.length > 0 ? `
        <h3 style="color:#1a1a2e;margin:0 0 12px 0;">
          💬 Responded Leads (${responded.length})
        </h3>
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <thead>
            <tr style="background:#f8f9fa;">
              <th style="padding:8px;text-align:left;">Lead</th>
              <th style="padding:8px;text-align:left;">Property</th>
              <th style="padding:8px;text-align:left;">Sentiment</th>
            </tr>
          </thead>
          <tbody>${respondedHtml}</tbody>
        </table>` : ''}
    </div>
    <div style="background:#f8f9fa;padding:16px 24px;border-top:1px solid #ddd;
      border-radius:0 0 8px 8px;font-size:12px;color:#888;">
      Powered by QualMatic AI | Drip Campaign Manager
    </div>
  </div>`;

const hasActiveSequences = active.length > 0 || responded.length > 0;

return [{
  json: {
    digestHtml,
    digestSubject: `🌅 Drip digest — ${active.length} active, ${responded.length} responded`,
    activeCount:    active.length,
    respondedCount: responded.length,
    completedCount: completed.length,
    hasActiveSequences,
    digestDate: new Date().toISOString().substring(0, 10)
  }
}];

const seqData = $('Parse & Store Email Content').first().json;
const config  = $('Set: Sequence Configuration').first().json;

// Define the remaining touches with their wait days
const touches = [
  {
    touchNumber:  2,
    waitDays:     parseInt(config.SEQUENCE_DAYS_2 || '4'),
    subject:      seqData.touch2Subject,
    body:         seqData.touch2Body,
    prevStatus:   'Touch 1 Sent',
    newStatus:    'Touch 2 Sent'
  },
  {
    touchNumber:  3,
    waitDays:     parseInt(config.SEQUENCE_DAYS_3 || '4'),
    subject:      seqData.touch3Subject,
    body:         seqData.touch3Body,
    prevStatus:   'Touch 2 Sent',
    newStatus:    'Touch 3 Sent'
  },
  {
    touchNumber:  4,
    waitDays:     parseInt(config.SEQUENCE_DAYS_4 || '6'),
    subject:      seqData.touch4Subject,
    body:         seqData.touch4Body,
    prevStatus:   'Touch 3 Sent',
    newStatus:    'Touch 4 Sent'
  },
  {
    touchNumber:  5,
    waitDays:     parseInt(config.SEQUENCE_DAYS_5 || '7'),
    subject:      seqData.touch5Subject,
    body:         seqData.touch5Body,
    prevStatus:   'Touch 4 Sent',
    newStatus:    'Touch 5 Sent'
  }
];

return touches.map(t => ({
  json: {
    ...t,
    sequenceId:      seqData.sequenceId,
    leadEmail:       seqData.leadEmail,
    agentName:       config.AGENT_NAME,
    agentEmail:      config.AGENT_EMAIL,
    gmailLabel:      config.GMAIL_LABEL
  }
}));

const batchItem = $('Process Touches Sequentially').item.json;
const allRows   = $input.all().map(i => i.json);

const match = allRows.find(row =>
  String(row['Sequence ID'] || '').trim() ===
  String(batchItem.sequenceId || '').trim()
);

if (!match) {
  return [{
    json: {
      ...batchItem,
      currentStatus: 'Not Found',
      isActive: false
    }
  }];
}

return [{
  json: {
    ...batchItem,
    currentStatus: match['Status'] || '',
    isActive: match['Status'] === batchItem.prevStatus
  }
}];

const item = $('Process Touches Sequentially').item.json;

function formatEmailHtml(text, agentName, agentEmail) {
  if (!text) return '';
  const paragraphs = text
    .split(/\n\s*\n/)
    .map(p => p.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  const body = paragraphs.map(p => `<p>${p}</p>`).join('');
  return `
    <div style="font-family:Arial,sans-serif;max-width:600px;color:#333;">
      ${body}
      <p style="color:#666;font-size:13px;margin-top:24px;">
        ${agentName}<br>${agentEmail}
      </p>
    </div>`;
}

return [{
  json: {
    ...item,
    emailHtml: formatEmailHtml(
      item.body,
      item.agentName,
      item.agentEmail
    )
  }
}];

const threadId = $json.threadId || $json.id;

return [{
  json: {
    threadId,
    originalId: $json.id,
    labels: $json.labels
  }
}];

const thread = $input.first().json;
const messages = thread.messages || [];

// Need at least 2 messages — original + reply
if (messages.length < 2) {
  return [{ json: { replyFound: false, reason: 'No reply yet — only original message in thread' } }];
}

// Latest message is always last in array
const reply = messages[messages.length - 1];

// Extract body from payload parts
function extractBody(payload) {
  if (!payload) return '';

  if (payload.mimeType === 'text/plain' && payload.body?.data) {
    return Buffer.from(payload.body.data, 'base64').toString('utf-8');
  }

  if (payload.parts) {
    for (const part of payload.parts) {
      if (part.mimeType === 'text/plain' && part.body?.data) {
        return Buffer.from(part.body.data, 'base64').toString('utf-8');
      }
      if (part.parts) {
        for (const nested of part.parts) {
          if (nested.mimeType === 'text/plain' && nested.body?.data) {
            return Buffer.from(nested.body.data, 'base64').toString('utf-8');
          }
        }
      }
    }
  }
  return '';
}

// Extract headers
const headers = reply.payload?.headers || [];
const getHeader = name => headers.find(h =>
  h.name.toLowerCase() === name.toLowerCase()
)?.value || '';

const from    = getHeader('From');
const subject = getHeader('Subject');
const body    = extractBody(reply.payload);

// Clean quoted text — remove everything after reply divider
const cleanBody = body
  .split(/\nOn .* wrote:/)[0]
  .split(/\n.*wrote:\n/)[0]
  .split(/\n-{3,}/)[0]
  .trim();

// Use snippet as fallback if body extraction fails
const finalBody = cleanBody || reply.snippet || body.substring(0, 500);

return [{
  json: {
    replyFound: true,
    replyId:    reply.id,
    threadId:   thread.id,
    from,
    subject,
    body:       finalBody,
    fullBody:   body,
    messageCount: messages.length
  }
}];
